export class Renderer extends RendererCanvas {

    dragTime = 0;
    boids: Boid[] = [];

    maxForce = 0.1;
    separationRadius = 25

    alignmentWeight = 1
    cohesionWeight = 1

    isMouseFollowing
    
    m =  new Vector3()

    constructor(div: any) {
        super(div);
        this.canvas.style.position = 'relative';
        this.canvas.style.width = '100%';
        this.canvas.style.height = '100%';

        // TODO
        // You code goes here for one time operation
        // 

            this.boids = Array.from({ length: 100 }, () => new Boid(Math.random() * 800, Math.random() * 600));

        this.start();
    }
    public mouseActivated(v: boolean) {
        this.isMouseFollowing = v
    }
    public mouseDown(x: number, y: number): void {

    }
    public mouseUp(x: number, y: number): void {

    }
    public mouseDrag(x: number, y: number): void {

    }
    public mouseMove(x: number, y: number): void {
        this.m.x = x;
        this.m.y = y;
    }
    public render(ctx: CanvasRenderingContext2D): void {
        // console.log(this.m)
        this.boids.forEach((boid) => {
            boid.maxForce = this.maxForce;
            boid.separationRadius = this.separationRadius;
            boid.alignmentWeight = this.alignmentWeight;
            boid.cohesionWeight = this.cohesionWeight;
            boid.update(this.boids, this.canvas.width, this.canvas.height, this.m, this.isMouseFollowing)
        });
        this.boids.forEach((boid) => boid.draw(this.ctx));

    }
}


class Vector3 {
    x
    y
    z
  constructor(x = 0, y = 0, z = 0) {
    this.x = x;
    this.y = y;
    this.z = z;
  }

  add(v) {
    this.x += v.x;
    this.y += v.y;
    this.z += v.z;
    return this;
  }

  sub(v) {
    this.x -= v.x;
    this.y -= v.y;
    this.z -= v.z;
    return this;
  }

  scale(scalar) {
    this.x *= scalar;
    this.y *= scalar;
    this.z *= scalar;
    return this;
  }

  distance(v) {
    return Math.sqrt((this.x - v.x) ** 2 + (this.y - v.y) ** 2 + (this.z - v.z) ** 2);
  }

  magnitude() {
    return Math.sqrt(this.x ** 2 + this.y ** 2 + this.z ** 2);
  }

  normalize() {
    const mag = this.magnitude();
    if (mag > 0) {
      this.x /= mag;
      this.y /= mag;
      this.z /= mag;
    }
    return this;
  }

  limit(max) {
    const mag = this.magnitude();
    if (mag > max && mag > 0) {
      const scale = max / mag;
      this.x *= scale;
      this.y *= scale;
      this.z *= scale;
    }
    return this;
  }

  clone() {
    return new Vector3(this.x, this.y, this.z);
  }
}

class Boid {
    position
    velocity
    acceleration
    maxSpeed
    maxForce
    perceptionRadius
    separationRadius
    separationWeight
    alignmentWeight
    cohesionWeight
    attractionWeight
  constructor(x, y) {
    this.position = new Vector3(x, y);
    this.velocity = new Vector3(Math.random() * 2 - 1, Math.random() * 2 - 1);
    this.acceleration = new Vector3();
    // Tunable parameters
    this.maxSpeed = 4;
    this.maxForce = 0.1;
    this.perceptionRadius = 100;
    this.separationRadius = 25;
    this.separationWeight = 1.5;
    this.alignmentWeight = 1.0;
    this.cohesionWeight = 1.0;
    
    this.attractionWeight = 1.0
  }

  update(boids, width, height, mousePos, isMouseFollowing) {
    const separation = new Vector3();
    const alignment = new Vector3();
    const cohesion = new Vector3();
    const attraction = new Vector3();

    let separationCount = 0;
    let alignmentCount = 0;
    let cohesionCount = 0;

    boids.forEach((other) => {
      if (other === this) return;
      const dist = this.position.distance(other.position);
      if (dist < this.perceptionRadius) {
        // Separation: Steer away from nearby boids
        if (dist < this.separationRadius && dist > 0) {
          const diff = this.position.clone().sub(other.position);
          diff.normalize().scale(1 / dist); // Stronger repulsion when closer
          separation.add(diff);
          separationCount++;
        }
        // Alignment: Match velocity of nearby boids
        alignment.add(other.velocity);
        alignmentCount++;
        // Cohesion: Steer toward the center of nearby boids
        cohesion.add(other.position);
        cohesionCount++;
      }
    });

    // Apply forces
    if (separationCount > 0) {
      separation.scale(1 / separationCount).normalize().scale(this.maxSpeed);
      separation.sub(this.velocity).limit(this.maxForce).scale(this.separationWeight);
      this.acceleration.add(separation);
    }
    if (alignmentCount > 0) {
      alignment.scale(1 / alignmentCount).normalize().scale(this.maxSpeed);
      alignment.sub(this.velocity).limit(this.maxForce).scale(this.alignmentWeight);
      this.acceleration.add(alignment);
    }
    if (cohesionCount > 0) {
      cohesion.scale(1 / cohesionCount); // Center of mass
      cohesion.sub(this.position).normalize().scale(this.maxSpeed);
      cohesion.sub(this.velocity).limit(this.maxForce).scale(this.cohesionWeight);
      this.acceleration.add(cohesion);
    }

    if (isMouseFollowing) {
        // Attraction to mouse
        if (mousePos && this.attractionWeight > 0) {
            attraction.add(mousePos).sub(this.position).normalize().scale(this.maxSpeed);
            attraction.sub(this.velocity).limit(this.maxForce).scale(this.attractionWeight);
            this.acceleration.add(attraction);
        }
    }

    // Update velocity and position
    this.velocity.add(this.acceleration).limit(this.maxSpeed);
    this.position.add(this.velocity);
    this.acceleration.scale(0); // Reset acceleration

    // Wrap around edges
    if (this.position.x < 0) this.position.x += width;
    if (this.position.x > width) this.position.x -= width;
    if (this.position.y < 0) this.position.y += height;
    if (this.position.y > height) this.position.y -= height;
  }

  draw(ctx) {
    // Draw as a triangle to show direction
    const angle = Math.atan2(this.velocity.y, this.velocity.x);
    const r = 6; // Size of the boid
    ctx.save();
    ctx.translate(this.position.x, this.position.y);
    ctx.rotate(angle);
    ctx.beginPath();
    ctx.moveTo(r, 0);
    ctx.lineTo(-r, r / 2);
    ctx.lineTo(-r, -r / 2);
    ctx.closePath();
    ctx.fillStyle = '#00f';
    ctx.fill();
    ctx.restore();
  }
}